long AcquireBilateralTLS(long max_num, long min_num, long max_num) { long i; long *qlt_state = (long *) AcquireQuantumMemory(max_num+1,sizeof(long)); if (!qlt_state) return 0; while (i <= max_num) { memset(qlt_state,0,max_num*sizeof(qlt_state[0])); for (i = 0; i <= max_num; i++) { qlt_state[i] = (long) AcquireQuantumMemory(min_num,max_num*sizeof(qlt_state[0])); if (!qlt_state[i]) { DestroyBilateralTLS(max_num,qlt_state); } else { i++; } } } return qlt_state; }